mapper.select:
SELECT gld.branch_id AS branchId, SUM(gld.debit) AS debit, SUM(gld.credit) AS credit, gl.`date` AS date, gld.chart_account_id AS chartAccountId, gld.company_id AS companyId, gld.location_id AS locationId, gld.customer_id AS customerId, gld.vendor_id AS vendorId, gld.employee_id AS employeeId, gld.other_id AS otherId, gld.class_id AS classId FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id WHERE gl.is_approve = 1 AND gl.is_active = 1 AND IFNULL(gl.is_retained_earnings,0) = 0 AND gld.company_id IN ( SELECT company_id FROM user_companies WHERE user_id = #{filter.userId} )
AND gl.`date` >= #{filter.dateFrom} AND gl.`date` <= #{filter.dateTo}
GROUP BY gl.`date`, gld.chart_account_id, gld.company_id, gld.location_id, gld.customer_id, gld.vendor_id, gld.employee_id, gld.other_id, gld.class_id

SELECT MONTH(m.month) AS month, COALESCE(expense.totalExpense, 0) AS totalExpenses, (COALESCE(revenue.totalRevenue, 0) - COALESCE(cogs.costGoodsSold, 0)) AS grossProfit, (COALESCE(revenue.totalRevenue, 0) - COALESCE(cogs.costGoodsSold, 0) - COALESCE(expense.totalExpense, 0)) AS profitLoss FROM ( SELECT DATE_FORMAT(gl.date, '%Y-%m-01') AS month FROM ${tableName} gl INNER JOIN chart_accounts ca ON gl.chart_account_id = ca.id INNER JOIN chart_account_groups g ON ca.chart_account_group_id = g.id INNER JOIN chart_account_types t ON g.chart_account_type_id = t.id WHERE g.is_active = 1 AND t.name IN ('Income','Other Income','Cost of Goods Sold','Expense')
AND gl.date >= #{filter.dateFrom} AND gl.date <= #{filter.dateTo}
GROUP BY YEAR(gl.date), MONTH(gl.date) ) AS m LEFT JOIN ( SELECT DATE_FORMAT(gl.date, '%Y-%m-01') AS month, SUM(IFNULL(gl.credit, 0)) - SUM(IFNULL(gl.debit, 0)) AS totalRevenue FROM ${tableName} gl INNER JOIN chart_accounts ca ON gl.chart_account_id = ca.id INNER JOIN chart_account_groups g ON ca.chart_account_group_id = g.id INNER JOIN chart_account_types t ON g.chart_account_type_id = t.id WHERE g.is_active = 1 AND t.name IN ('Income','Other Income')
AND gl.date >= #{filter.dateFrom} AND gl.date <= #{filter.dateTo}
GROUP BY YEAR(gl.date), MONTH(gl.date) ) AS revenue ON m.month = revenue.month LEFT JOIN ( SELECT DATE_FORMAT(gl.date, '%Y-%m-01') AS month, SUM(IFNULL(gl.debit, 0)) - SUM(IFNULL(gl.credit, 0)) AS costGoodsSold FROM ${tableName} gl INNER JOIN chart_accounts ca ON gl.chart_account_id = ca.id INNER JOIN chart_account_groups g ON ca.chart_account_group_id = g.id INNER JOIN chart_account_types t ON g.chart_account_type_id = t.id WHERE g.is_active = 1 AND t.name IN ('Cost of Goods Sold')
AND gl.date >= #{filter.dateFrom} AND gl.date <= #{filter.dateTo}
GROUP BY YEAR(gl.date), MONTH(gl.date) ) AS cogs ON m.month = cogs.month LEFT JOIN ( SELECT DATE_FORMAT(gl.date, '%Y-%m-01') AS month, SUM(IFNULL(gl.debit, 0)) - SUM(IFNULL(gl.credit, 0)) AS totalExpense FROM ${tableName} gl INNER JOIN chart_accounts ca ON gl.chart_account_id = ca.id INNER JOIN chart_account_groups g ON ca.chart_account_group_id = g.id INNER JOIN chart_account_types t ON g.chart_account_type_id = t.id WHERE g.is_active = 1 AND t.name IN ('Expense') AND g.is_depreciation NOT IN (2, 3)
AND gl.date >= #{filter.dateFrom} AND gl.date <= #{filter.dateTo}
GROUP BY YEAR(gl.date), MONTH(gl.date) ) AS expense ON m.month = expense.month ORDER BY m.month

SELECT ca.id AS id, CONCAT(ca.account_codes, ' - ', ca.account_description) AS name, COALESCE(SUM(gld.credit) - SUM(gld.debit), 0) AS amount FROM chart_accounts ca INNER JOIN chart_account_groups g ON ca.chart_account_group_id = g.id INNER JOIN chart_account_types t ON g.chart_account_type_id = t.id INNER JOIN general_ledger_details gld ON gld.chart_account_id = ca.id INNER JOIN general_ledgers gl ON gl.id = gld.general_ledger_id WHERE ca.is_active = 1 AND g.is_active = 1 AND t.name IN ('Income','Other Income') AND gl.is_active = 1 AND gl.is_approve = 1 AND IFNULL(gl.is_retained_earnings,0) = 0 AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND gld.branch_id IN
#{branchId}
AND gl.date >= #{filter.dateFrom} AND gl.date <= #{filter.dateTo}
GROUP BY ca.id, ca.account_codes, ca.account_description HAVING amount > 0 ORDER BY ca.account_codes

SELECT g.id AS id, g.name AS name, IFNULL( ( SELECT SUM(debit) FROM general_ledger_details AS glb WHERE chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id) AND company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND glb.branch_id IN
#{branchId}
AND (SELECT DATE(date) FROM general_ledgers WHERE id = general_ledger_id) >= DATE(#{filter.dateFrom}) AND (SELECT DATE(date) FROM general_ledgers WHERE id = general_ledger_id) <= DATE(#{filter.dateTo}) AND (SELECT YEAR(date) FROM general_ledgers WHERE id = general_ledger_id) >= YEAR(#{filter.dateFrom}) AND (SELECT YEAR(date) FROM general_ledgers WHERE id = general_ledger_id) <= YEAR(#{filter.dateTo})
) + ( SELECT SUM(credit) FROM general_ledger_details AS glb WHERE chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id) AND company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND glb.branch_id IN
#{branchId}
AND (SELECT DATE(date) FROM general_ledgers WHERE id = general_ledger_id) >= DATE(#{filter.dateFrom}) AND (SELECT DATE(date) FROM general_ledgers WHERE id = general_ledger_id) <= DATE(#{filter.dateTo}) AND (SELECT YEAR(date) FROM general_ledgers WHERE id = general_ledger_id) >= YEAR(#{filter.dateFrom}) AND (SELECT YEAR(date) FROM general_ledgers WHERE id = general_ledger_id) <= YEAR(#{filter.dateTo})
), 0 ) AS amount FROM chart_account_groups g INNER JOIN chart_account_types t ON g.chart_account_type_id=t.id WHERE g.is_active=1 AND t.name IN ('Expense', 'Other Expense') AND g.is_depreciation NOT IN (2,3) HAVING amount > 0 ORDER BY t.id

SELECT 'Invoice' AS name, COUNT(*) AS amount FROM `sales_orders` AS so WHERE so.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId}) AND so.status > 0 AND so.discount = 0 AND so.id NOT IN ( SELECT sales_order_id FROM credit_memos WHERE status > 0
AND MONTH(credit_memos.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(credit_memos.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(credit_memos.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(credit_memos.order_date) <= YEAR(#{filter.dateTo})
)
AND MONTH(so.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(so.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(so.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(so.order_date) <= YEAR(#{filter.dateTo})
AND so.branch_id IN
#{branchId}

SELECT 'CM Invoice' AS name, COUNT(*) AS amount FROM `sales_orders` AS so WHERE so.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId}) AND so.status > 0 AND so.discount = 0 AND so.id IN ( SELECT sales_order_id FROM credit_memos WHERE status > 0
AND MONTH(order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(order_date) <= MONTH(#{filter.dateTo}) AND YEAR(order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(order_date) <= YEAR(#{filter.dateTo})
)
AND MONTH(so.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(so.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(so.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(so.order_date) <= YEAR(#{filter.dateTo})
AND so.branch_id IN
#{branchId}

SELECT ( SELECT COUNT(*) FROM sales_orders AS so WHERE so.status > 0 AND so.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND so.branch_id IN
#{branchId}
AND MONTH(so.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(so.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(so.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(so.order_date) <= YEAR(#{filter.dateTo})
) AS totalInvoice, ( COALESCE( (SELECT SUM(so.total_amount - IFNULL(so.discount, 0)) FROM sales_orders AS so WHERE so.status > 0 AND so.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND so.branch_id IN
#{branchId}
AND MONTH(so.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(so.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(so.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(so.order_date) <= YEAR(#{filter.dateTo})
), 0 ) - COALESCE( (SELECT SUM(cm.total_amount - IFNULL(cm.discount, 0)) FROM credit_memos AS cm WHERE cm.status > 0 AND cm.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND cm.branch_id IN
#{branchId}
AND MONTH(cm.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(cm.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(cm.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(cm.order_date) <= YEAR(#{filter.dateTo})
), 0 ) ) AS totalAmount, ( (COALESCE( (SELECT SUM(so.total_amount - IFNULL(so.discount, 0)) FROM sales_orders AS so WHERE so.status > 0 AND so.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND so.branch_id IN
#{branchId}
AND MONTH(so.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(so.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(so.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(so.order_date) <= YEAR(#{filter.dateTo})
), 0) - COALESCE( (SELECT SUM(cm.total_amount - IFNULL(cm.discount, 0)) FROM credit_memos AS cm WHERE cm.status > 0 AND cm.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND cm.branch_id IN
#{branchId}
AND MONTH(cm.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(cm.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(cm.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(cm.order_date) <= YEAR(#{filter.dateTo})
), 0) ) / NULLIF(( SELECT COUNT(*) FROM sales_orders AS so WHERE so.status > 0 AND so.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND so.branch_id IN
#{branchId}
AND MONTH(so.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(so.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(so.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(so.order_date) <= YEAR(#{filter.dateTo})
), 0) ) AS average, ( SELECT MAX(so.total_amount - IFNULL(so.total_deposit, 0)) FROM sales_orders AS so WHERE so.status > 0 AND so.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND so.branch_id IN
#{branchId}
AND MONTH(so.order_date) >= MONTH(#{filter.dateFrom}) AND MONTH(so.order_date) <= MONTH(#{filter.dateTo}) AND YEAR(so.order_date) >= YEAR(#{filter.dateFrom}) AND YEAR(so.order_date) <= YEAR(#{filter.dateTo})
) AS largest

SELECT
    COUNT(*) AS Bills,
    (COALESCE((
        SELECT SUM(po.total_amount - IFNULL(po.discount_amount, 0))
        FROM purchase_orders po
        WHERE po.status > 0
          AND DATE(po.order_date) >= #{filter.dateFrom}
          AND DATE(po.order_date) <= #{filter.dateTo}

            AND po.branch_id IN

                #{branchId}


    ),0)
    - COALESCE((
        SELECT SUM(pr.total_amount)
        FROM purchase_returns pr
        WHERE pr.status > 0
          AND DATE(pr.order_date) >= #{filter.dateFrom}
          AND DATE(pr.order_date) <= #{filter.dateTo}

            AND pr.branch_id IN

                #{branchId}


    ),0)) AS totalAmount,
    (COALESCE((
        SELECT SUM(po.total_amount - IFNULL(po.discount_amount, 0))
        FROM purchase_orders po
        WHERE po.status > 0
          AND DATE(po.order_date) >= #{filter.dateFrom}
          AND DATE(po.order_date) <= #{filter.dateTo}

            AND po.branch_id IN

                #{branchId}


    ),0)
    - COALESCE((
        SELECT SUM(pr.total_amount)
        FROM purchase_returns pr
        WHERE pr.status > 0
          AND DATE(pr.order_date) >= #{filter.dateFrom}
          AND DATE(pr.order_date) <= #{filter.dateTo}

            AND pr.branch_id IN

                #{branchId}


    ),0)) / NULLIF(COUNT(*),0) AS Average,
    (SELECT MAX(po.total_amount)
     FROM purchase_orders po
     WHERE po.status > 0
       AND DATE(po.order_date) >= #{filter.dateFrom}
       AND DATE(po.order_date) <= #{filter.dateTo}

        AND po.branch_id IN

            #{branchId}


    ) AS Largest
FROM purchase_orders AS po
WHERE po.status > 0
  AND DATE(po.order_date) >= #{filter.dateFrom}
  AND DATE(po.order_date) <= #{filter.dateTo}

    AND po.branch_id IN

        #{branchId}

SELECT this_year.order_month AS month, this_year.totalAmount AS totalThisYear, last_year.totalAmount AS totalLastYear, CASE WHEN last_year.totalAmount = 0 THEN 0 ELSE (this_year.totalAmount - last_year.totalAmount) / last_year.totalAmount * 100 END AS growthRate FROM (SELECT MONTH(so.order_date) AS order_month, SUM(so.total_amount - IFNULL(so.discount, 0) - IFNULL(so.total_deposit, 0)) AS totalAmount FROM sales_orders AS so WHERE status > 0
AND so.branch_id IN
#{branchId}
AND YEAR(so.order_date) = YEAR(#{filter.dateTo}) AND MONTH(so.order_date) BETWEEN MONTH(#{filter.dateFrom}) AND MONTH(#{filter.dateTo}) GROUP BY MONTH(so.order_date) ) AS this_year LEFT JOIN (SELECT MONTH(so.order_date) AS order_month, SUM(so.total_amount - IFNULL(so.discount, 0) - IFNULL(so.total_deposit, 0)) AS totalAmount FROM sales_orders AS so WHERE status > 0
AND so.branch_id IN
#{branchId}
AND YEAR(so.order_date) = YEAR(#{filter.dateFrom}) - 1 AND MONTH(so.order_date) BETWEEN MONTH(#{filter.dateFrom}) AND MONTH(#{filter.dateTo}) GROUP BY MONTH(so.order_date) ) AS last_year ON this_year.order_month = last_year.order_month ORDER BY this_year.order_month;

SELECT this_year.order_month AS month, this_year.totalAmount AS grandTotalThisYear, last_year.totalAmount AS grandTotalLastYear, CASE WHEN last_year.totalAmount = 0 OR last_year.totalAmount IS NULL THEN 0 ELSE (this_year.totalAmount - last_year.totalAmount) / last_year.totalAmount * 100 END AS grandTotalGrowthRate FROM ( SELECT MONTH(so.order_date) AS order_month, SUM(so.total_amount - IFNULL(so.discount, 0) - IFNULL(so.total_deposit, 0)) AS totalAmount FROM sales_orders AS so WHERE status > 0
AND so.branch_id IN
#{branchId}
AND YEAR(so.order_date) = YEAR(#{filter.dateTo}) AND MONTH(so.order_date) BETWEEN MONTH(#{filter.dateFrom}) AND MONTH(#{filter.dateTo}) GROUP BY MONTH(so.order_date) ) AS this_year LEFT JOIN ( SELECT MONTH(so.order_date) AS order_month, SUM(so.total_amount - IFNULL(so.discount, 0) - IFNULL(so.total_deposit, 0)) AS totalAmount FROM sales_orders AS so WHERE status > 0
AND so.branch_id IN
#{branchId}
AND YEAR(so.order_date) = YEAR(#{filter.dateFrom}) - 1 AND MONTH(so.order_date) BETWEEN MONTH(#{filter.dateFrom}) AND MONTH(#{filter.dateTo}) GROUP BY MONTH(so.order_date) ) AS last_year ON this_year.order_month = last_year.order_month ORDER BY this_year.order_month;

SELECT SUM(credit) AS amount, GROUP_CONCAT(purchase_order_id) AS purchaseOrderId, GROUP_CONCAT(main_gl_id) AS arrMainGlId, GROUP_CONCAT(gl.id) AS arrGlId FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id WHERE is_active = 1 AND chart_account_id IN ( SELECT id FROM chart_accounts WHERE is_active = 1 AND chart_account_type_id IN ( SELECT id FROM chart_account_types WHERE name = 'Accounts Payable' ) ) AND company_id IN ( SELECT company_id FROM user_companies WHERE user_id = 1 ) AND vendor_id IN ( SELECT vendors.id FROM vendors WHERE payment_term_id IN ( SELECT id FROM payment_terms WHERE is_active = 1 ) )
AND MONTH(date) >= MONTH(#{filter.dateFrom}) AND MONTH(date) <= MONTH(#{filter.dateTo}) AND YEAR(date) >= YEAR(#{filter.dateFrom}) AND YEAR(date) <= YEAR(#{filter.dateTo})
AND gld.branch_id IN
#{branchId}
AND credit > 0 AND purchase_order_id IS NOT NULL AND purchase_return_receipt_id IS NULL;

SELECT SUM(credit) AS amount, GROUP_CONCAT(gl.id) AS arr_gl_id FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id WHERE is_active = 1 AND chart_account_id IN ( SELECT id FROM chart_accounts WHERE is_active = 1 AND chart_account_type_id IN ( SELECT id FROM chart_account_types WHERE name = 'Accounts Receivable' ) ) AND company_id IN (SELECT company_id FROM user_companies WHERE user_id = 1) AND customer_id IN ( SELECT customers.id FROM customers WHERE payment_term_id IN ( SELECT id FROM payment_terms WHERE is_active = 1 ) ) AND ADDDATE(`date`, INTERVAL #{netDay} DAY) < #{filter.dateFrom} AND credit > 0 AND sales_order_id IS NOT NULL AND ( sales_order_id IN (${saleOrderId})
OR main_gl_id IN (${arrMainGlId})
)

SELECT SUM(credit) AS amount, GROUP_CONCAT(gl.id) AS arr_gl_id FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id WHERE is_active=1 AND chart_account_id IN ( SELECT id FROM chart_accounts WHERE is_active=1 AND chart_account_type_id IN ( SELECT id FROM chart_account_types WHERE name='Accounts Receivable' ) ) AND company_id IN (SELECT company_id FROM user_companies WHERE user_id = 1) AND customer_id IN ( SELECT customers.id FROM customers WHERE payment_term_id IN ( SELECT id FROM payment_terms WHERE is_active = 1 ORDER BY net_days ) ) AND ADDDATE(`date`, INTERVAL #{netDay} DAY) < #{filter.dateFrom} AND credit>0 AND sales_order_id IS NOT NULL AND ( sales_order_id IN (${saleOrderId})
OR main_gl_id IN (${arrMainGlId})
)
